"""Preserve29 pending low-rank Transmutation spells and physical-system questions."""
from copy import deepcopy
import json,hashlib
from prepare_low_illusion_spell_source_audit import ROOT,GAME,AUDIT,current_book_rows,digest
from prepare_combat_feat_source_audit import section
QUESTIONS={
 'shimmerstep':'Preserve5ft movement without opportunity attacks. Decide self target, actual movement versus teleportation, terrain/cost, occupied destination, speed0/restraint and three-dimensional support. Core one Action remains unless explicitly changed. No extra ordinary movement, escape from every restraint, phasing through obstacles or deferred free step.',
 'stone-touch':'Preserve hardening one small object/surface and+1AC for1round if armor. Define size/material, worn/held willingness, whether object structural AC changes versus wearer AC, eligible armor and modifier family. It does not automatically restoreHP, remove damage/flaws, change grade, create stone or grant resistance/weapon effects.',
 'mold-matter':'Preserve reshaping actual dirt,wood or stone in1cubicfoot. Define range/access, attached versus loose mass, detail/work speed, structural support and permanence under Instantaneous. Track retained mass/material identity; no extra raw material, repaired quality, free completed crafted machine, magical-assembly replacement or arbitrary creature damage.',
 'fleeting-flight':'Preserve float5ft for1turn and terrain-penalty avoidance. Resolve whether5ft is altitude/displacement/range, actual target, horizontal motion and turn expiry against Core Instantaneous. Define load, unsupported endings and falling. No unlimited flight speed, repeated hover without real casting/actions, free carried creatures or terrain/hazard immunity beyond the text.',
 'snap-freeze':'Preserve chilling a drink,preserving food or freezing1ft square. Define separate finite target volumes/thickness, temperature limits, duration and actual preservation mechanism. Reconcile with reviewed food-age/spoilage ledgers; no age reset, sterilization, magical stasis, bonus nutrition, unlimited refrigeration or cold damage solely from the name.',
 'flicker-skin':'Preserve+1AC against one attack and explicit concentration despite Core Instantaneous. Define self/other target, expiry, commitment/consumption and stacking with Flickerstep,Stone Touch and existing defenses. No permanent skin change, resistance, hidden extra formHP or renewal through canceled attacks without a new legitimate cast.',
 'primal-savagery':'Preserve formed hand claws and1d10 acid. Set exact attack resolution/reach and actual hands despite Core30ft, duration and whether the Action includes one strike. Distinguish a source-specific spell attack from permanent natural weapons or transformation. No automatic cantrip scaling, extra attacks, free magic-item use or acid material production.',
 'control-flames':'Preserve manipulating actual fire in5ft cube with concentration up to1minute. Define finite modes, source/range distinction, fuel/oxygen, magical-fire eligibility, movement/expansion/extinguishing and affected creatures. No unprinted damage, arbitrary source-spell control, flame creation, permanent fuel, temperature immunity or broad industrial output.',
 'thaumaturgy':'Define a finite menu for minor supernatural effects, actual targets/ranges/durations, simultaneous limits and action costs from the sparse source. Preserve harmless/mundane interaction limits where chosen explicitly; no external-game menu by assumption, divine authority, cosmology, compulsion, hidden information, damage or free crafted resources.',
 'featherstep':'Preserve both fall-damage negation and movement across fragile surfaces. Define target,lifetime,concentration, fall timing and support/load limit with Core Action/30ft/Instantaneous. Distinguish the reviewed Feather Fall procedure. Surface support does not erase actual pounds/Load, fly over empty space or prevent unrelated collision/hazard damage.',
 'weaponbend':'Preserve target weapon bending and failedSTR-save disarm. Define held weapon eligibility, size/material/magic, save owner, effect on success, object placement and whether deformation persists or changes weapon function. No automatic weapon destruction, generic repair bill, natural-limb disarm or stolen ownership; resolve multiple weapons and secured grips.',
 'feral-might':'Preserve+2STR and+1melee damage as two clauses. Define actual ability-score change/cap,derived modifier updates, affected damage events, target/lifetime/concentration and same-source replacement. Resolve carrying/check/attack interactions without duplicated ability damage, extraHP, permanent advancement or unused resource reset.',
 'steel-skin':'Preserve resistance to bludgeoning,piercing,slashing for3hits. Define duration,target and exactly which actual hit consumes a use, mixed damage and no-damage hits, ongoing damage versus attacks and multiattack timing. Apply Core resistance rounding once; no implied nonmagical-only qualifier, armor change, heal/HP buffer or reset when resistance is suppressed.',
 'magnetic-grip':'Preserve holding a metallic object or creature in place withSTR resistance. Define metallic eligibility versus merely worn metal, size/mass/support, target save, duration/concentration and end/escape. Specify bounded movement restraint rather than automatically adding every Restrained effect. No crushing damage, levitation, remote limb disarm or universal metal detection.',
 'unravel-threads':'Preserve destroying one nonmagical rope,knot or textile object. Define finite size/mass,actual target/access, worn/held resistance and knot versus entire object choice. Preserve contents/location and falling consequences on loss of support. No magical Tailoring destruction, living-tissue damage, material multiplication or unstated dismantling/salvage yield.',
 'expeditious-retreat':'Preserve doubling your speed and BonusAction Dash,not an external narrower version. Set self target,lifetime/concentration and whether the casting BonusAction itself includes Dash or only enables later ones. Apply current speed layers and speed0 limits; no extra BonusAction, additional multiplied Dash pool or damage from erroneous Core Damage tag.',
 'absorb-elements':'Resolve triggering damage versus Core one-Action casting through an explicit finite timing decision. Define eligible damage types,resistance duration and whether it protects the triggering event, then exact additional damage/trigger/expiry on the next attack. Preserve action/RP/interruption timing,no retrospective mitigation and no imported external die amount.',
 'catapult':'Preserve an actual1–5lb object and3d8 bludgeoning. Define access/held resistance, trajectory/range,attack or save,collision/cover,object damage and final custody. No automatic potion,poison,explosive or crafted-item activation from impact; additional payload rules need independent authority. One real object cannot be duplicated or silently refunded.',
 'enlarge-reduce':'Preserve grows/shrinks by50percent and explicitly settle linear dimensions versus size category,mass and carried gear. Define target/willingness,save,lifetime/concentration,space/preflight,fit/hands/meld and end placement. No silent external double-size/eightfold-mass profile,HP/heal reset,implied weapon damage or unbounded alternating material gain.',
 'grease':'Preserve10ft-square slippery surface; distinguish placement range from area. Define target surface,depth,lifetime,concentration,movement and save/check timing,Prone and difficult-terrain effects if authorized. Clarify real substance versus maintained magic and ignition/cleanup,without imported flammability,valuable grease supply or infinite entry-trigger damage.',
 'alter-fluid':'Preserve changes to liquid temperature,viscosity or color. Define finite volume/temperature/viscosity bounds,actual liquid access,hostile/contained targets,duration/reversion and mass conservation. Decide food,water,poison,crafting and storage interfaces explicitly; no automatic purification,nutrition,rare transmutation,physiology attack or age/consumption reset.',
 'transmute-weapon':'Preserve changing actual weapon type and damage to another physical form. Define finite eligible forms,physical damage types,proficiency/hands/reach/ammunition,grade/magic attachments,durability and mass,save/custody,lifetime/reversion. No copy of a weapon,free value upgrade,resource refill,arbitrary elemental type or attack gained from the transformation.',
 'swiftness':'Preserve+10 movement,+1AC and difficult-terrain immunity for1minute. Define movement types,modifier families,target/concentration and speed ordering with doubles,slows,restraint and different terrain sources. Ignoring difficult-terrain cost does not grant traversability,flight,immunity to environmental damage or extra action resources.',
 'stone-shape':'Retain rank2 and rank4 placements/Core versions with5/60ft ranges and3/7RP. Reconcile one ordinary identity and unassigned variant explicitly. Define5ft extent/volume,available stone,mass,detail,structural support,workability and formed doors/bridges/traps. No free clockwork,hidden knowledge,magical resources or automatic trap damage; higher any-form text remains preserved.',
 'disable-limb':'Preserve DEX-save arm/leg choice yielding attack disadvantage or half speed. Define eligible anatomy,which attacks/movement types,lifetime/concentration,repeat/escape and multiple-cast family. It does not automatically remove a limb,force dropping items,disable spell components,halve all anatomy repeatedly or grant Wounded/Paralyzed.',
 'alter-self':'Preserve appearance change or adaptations such as water breathing. Author a finite self-only mode menu,lifetime/concentration,mode changes,actual anatomy/fit/gear/voice/senses and movement. Distinguish adaptation from a separate formHP pool or reviewed Polymorph. No inherited whole-creature stats,free gear,ability/healing reset or cosmology-defined origin.',
 'darkvision':'Define actual target,lifetime/concentration,vision distance,color/light-level interpretation and ordinary versus magical darkness,including existing stronger senses. Does not grant seeing through objects/invisibility,knowledge of hidden locations or automatic Perception success. All required operational numbers absent from source need explicit NEW decisions.',
 'enhance-ability':'Preserve advantage on checks for one chosen ability. Define target,lifetime/concentration,selection timing and same-source recasting. Keep genuine ability checks distinct from saves,attacks,damage,automatic outcomes and costs/material/time of any craft. No imported animal-mode riders,HP buffer,score increase or multiple advantages defeating disadvantage.',
 'levitate':'Preserve target floating up to20ft and resolve whether20ft is range,altitude or both. Define eligible size/mass,willingness/save,support,vertical/horizontal movement and caster actions,duration/concentration and safe/unsafe ending. Preserve actual load,cargo,restraints,elevation and falling; no unlimited flight,implicit movement speed or body/mass duplication.'}
PENDING_COUNTERPARTS=['mage-hand','flickerstep','shadow-blade','blurred-visage','prestidigitation']
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def dump(p,d):p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def main():
    inherited=json.loads((AUDIT/'LOW_ILLUSION_SPELL_SOURCE_PREPARATION.json').read_text(encoding='utf-8'));protected=deepcopy(inherited['protectedFiles']);assert all(sha(GAME/p)==h for p,h in protected.items())
    def read(p):protected[p.relative_to(GAME).as_posix()]=sha(p);return json.loads(p.read_text(encoding='utf-8-sig'))
    catalog=read(ROOT/'data/public/spell_playtests/catalog.json');rows=catalog['spells'];by={r['id']:r for r in rows};selected=[r for r in rows if r['operational'] is None and r['schools'][0]=='Transmutation' and min(v['rank'] for v in r['classAccess'].values())<=2]
    assert len(selected)==29 and {r['id'] for r in selected}==set(QUESTIONS)
    universal=read(AUDIT/'LOW_UNIVERSAL_SPELL_SOURCE_PREPARATION.json');prior={r['spellId'] for d in (inherited,universal) for r in d['selectedSpells']};assert len(prior)==49 and not prior.intersection(QUESTIONS)
    source=read(ROOT/'data/playtest/spell_sources/catalog.json');core=read(ROOT/'data/public/Decennium_Descent_Core_Systems_Data_v2_Known_Descent.json');book=current_book_rows();bindings=[]
    for r in selected:
        assert r['source']['original']==source[r['id']]
        for e in r['source']['coreEntries']+r['source']['possibleHistoricalAliases']:assert e['original']==core['spells'][e['index']]
        for placement in r['source']['original']['placements']:
            matches=[b for b in book if b['name']==r['name'] and b['school']==placement['school'] and b['level']==placement['level']];assert len(matches)==1
            bindings.append({'spellId':r['id'],'catalogPlacement':placement,'currentBookRow':matches[0],'summaryDifferencePreserved':placement['summary']!=matches[0]['summary']})
    counterparts=[r for r in rows if r['operational'] is not None and 'Transmutation' in r['schools']]+[by['feather-fall']]+[by[id] for id in PENDING_COUNTERPARTS]
    assert len({r['id'] for r in counterparts})==len(counterparts)
    mentions=[r for r in read(ROOT/'data/public/spell_playtests/class_name_mentions_for_review.json') if r.get('spellId') in QUESTIONS];cm=read(ROOT/'data/public/class_playtests/manifest.json');classes={r['class']:r for r in cm['classes']};class_records=[]
    for m in mentions:
        p=(ROOT/'docs/mechanics'/classes[m['class']]['data']).resolve();d=read(p)
        if m['location']=='engine':record={'engine':d.get('engine',[])}
        else:
            matches=[c for c in d['cards'] if c['id']==m['location']];assert len(matches)==1;record={'card':matches[0]}
        class_records.append({'mention':m,**record,'file':p.relative_to(GAME).as_posix(),'scope':'Textual comparison only; no ordinary spell grant or identity merge.'})
    excerpts=deepcopy(inherited['currentGoverningExcerpts'])
    extra={'TRANSFORMATION_SPELL_PLAYTEST.md':None,'FORM_TEMP_HP_PLAYTEST.md':None,'CRAFTING_HARVEST_PLAYTEST.md':['Material identity, consumption and substitution','Identify and harvest','Preservation and spoilage'],'COOKING_RECIPE_PLAYTEST.md':['Food mass and the food ledger','Cooking, stabilization and storage'],'EQUIPMENT_ACQUISITION_PLAYTEST.md':['Armor and shields','Fit and size'],'CONTROL_STATES_PLAYTEST.md':['Speed arbitration','Root, physical restraints and suppression']}
    for name,heads in extra.items():
        p=ROOT/'docs/mechanics'/name;t=p.read_text(encoding='utf-8');protected[p.relative_to(GAME).as_posix()]=sha(p)
        for h in heads or [None]:excerpts.append({'file':p.relative_to(GAME).as_posix(),'sha256':sha(p),'heading':h or 'entire guide','exactText':section(t,h) if h else t})
    variants=[{'spellId':r['id'],'completeCatalogPlacements':r['source']['original']['placements'],'completeCoreRows':r['source']['coreEntries']} for r in selected if len(r['source']['coreEntries'])>1]
    records=[{'spellId':r['id'],'questionId':f'TR-{i+1:02}','fullSourceAndCurrentAccessRecord':r,'recordSha256':digest(r),'individualQuestion':QUESTIONS[r['id']]} for i,r in enumerate(selected)]
    checks=[('29 exact remaining low-rank Transmutation identities',len(records)==29),('Disjoint from49 earlier focused pending sources',not prior.intersection(QUESTIONS)),('All original catalog and Core source rows retained exactly',True),('30 exact current-book bindings preserve any wording difference',len(bindings)==30),('276 operational and572 pending identities retained',sum(r['operational'] is not None for r in rows)==276 and sum(r['operational'] is None for r in rows)==572),('Every full source has an individual question',all(len(r['individualQuestion'])>190 for r in records)),('Stone Shape rank2/rank4 variants retained without automatic promotion',[r['spellId'] for r in variants]==['stone-shape']),('18 operational andfive pending counterparts preserve distinct identities',len(counterparts)==23 and sum(r['operational'] is not None for r in counterparts)==18),('Every current class mention bound to its actual source',len(class_records)==len(mentions)),('All governing excerpts exact',all(z['exactText'] in (GAME/z['file']).read_text(encoding='utf-8') for z in excerpts)),('All protected inputs unchanged',all(sha(GAME/p)==h for p,h in protected.items()))]
    assert all(v for _,v in checks),[n for n,v in checks if not v]
    counts={'sourceSpells':848,'operationalSpells':276,'remaining':572,'selectedLowTransmutation':29,'exactCoreEntries':sum(len(r['source']['coreEntries']) for r in selected),'currentBookBindings':30,'reviewedCounterparts':18,'pendingCounterparts':5,'classComparisonRecords':len(class_records),'governingExcerpts':len(excerpts),'multiCoreVariants':1,'currentBookSummaryDifferences':sum(r['summaryDifferencePreserved'] for r in bindings),'focusedPendingSpellSourcesPrepared':78}
    data={'status':'prepared-not-sent; source questions only','commonOperationalQuestion':inherited['commonOperationalQuestion'],'selectedSpells':records,'currentBookBindings':bindings,'completeCounterparts':counterparts,'classComparisonRecords':class_records,'multiPlacementCoreVariants':variants,'currentGoverningExcerpts':excerpts,'currentRankCosts':catalog['costByRank'],'currentClassProgression':catalog['classProgression'],'counts':counts,'checks':[{'name':n,'pass':v} for n,v in checks],'protectedFiles':protected,'spellsApproved':0,'sourceInformationDeleted':0,'cosmology':'post-push only; supernatural/body/material names create no origin or cosmic permissions','futureDispatch':'Rebase dependencies after active Fishing review; source decisions precede authoring and exact review. Crafting and preservation promises require finite interfaces,not deletion.'}
    dump(AUDIT/'LOW_TRANSMUTATION_SPELL_SOURCE_PREPARATION.json',data)
    lines=['# Low-rank Transmutation spell source audit','',data['status'],'',data['commonOperationalQuestion'],'','All 29 selected identities retain 30 complete Core rows and 30 current-book placements. Stone Shape keeps its rank-two/rank-four source differences. Eighteen previously operational counterparts and five pending comparison identities remain distinct. Actual material, food age, body size, equipment custody, movement and modifier families require source-specific decisions; no spell promise is removed by this preparation.','', '| Case | Spell | Full-source question |','|---|---|---|']
    lines += [f"| {r['questionId']} | {r['fullSourceAndCurrentAccessRecord']['name']} ({r['spellId']}) | {r['individualQuestion']} |" for r in records]
    lines+=['','These three prepared spell cohorts cover78 distinct pending identities. Totals remain276 operational and572 unfinished. Sources, prior reviewed effects and all current guides remain unchanged. Fishing is the active source conference; do not interrupt or resend. Human balance, runtime and broader flow remain separate. Cosmology stays after the verified GitHub push.','']
    text='\n'.join(lines);(AUDIT/'LOW_TRANSMUTATION_SPELL_SOURCE_AUDIT.md').write_text(text,encoding='utf-8')
    packet='PREPARED LOW-RANK TRANSMUTATION SOURCE CONFERENCE — NOT SENT.\n\n'+text+'\nCOMPLETE SOURCE AND CURRENT DEPENDENCY EVIDENCE\n'+json.dumps(data,ensure_ascii=False,separators=(',',':'))
    p=AUDIT/'CODEX_LOW_TRANSMUTATION_SPELL_SOURCE_PREPARED.txt';p.write_text(packet,encoding='utf-8',newline='\n')
    status={'status':'prepared-not-sent','packetFile':p.name,'characters':len(packet),'packetSha256':sha(p),'counts':counts,'checkCount':len(checks),'protectedFilesUnchanged':len(protected),'spellsApproved':0,'sourceInformationDeleted':0,'cosmology':'post-push only'};dump(AUDIT/'LOW_TRANSMUTATION_SPELL_SOURCE_STATUS.json',status);print(json.dumps(status))
if __name__=='__main__':main()
